import {useEffect,useMemo,useState} from 'react';
import {CircleDollarSign,FileText,Plus,ReceiptIndianRupee,Search,X} from 'lucide-react';
import {createBillableService,createInvoice,getBillingOverview,getClientBilling,getInvoice,issueInvoice,listBillableServices,listInvoices,listPayments,recordInvoicePayment} from '../../lib/practiceOperationsApi';

const money=(minor=0,currency='INR')=>new Intl.NumberFormat(undefined,{style:'currency',currency}).format(Number(minor)/100);
const today=()=>new Date().toISOString().slice(0,10);
const emptyLine=()=>({service_id:'',description:'',quantity:1,unit_price:'',discount_type:'NONE',discount_value:'0',tax_type:'NO_TAX',tax_rate:'0'});
function Field({label,children}){return <label className="text-sm font-semibold text-slate-700">{label}{children}</label>}
function Modal({title,onClose,children}){return <div className="fixed inset-0 z-[90] flex items-end bg-slate-950/50 sm:items-center sm:justify-center sm:p-4"><section role="dialog" aria-modal="true" aria-label={title} className="max-h-[92dvh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 sm:max-w-2xl sm:rounded-3xl sm:p-6"><div className="flex items-center justify-between"><h3 className="text-xl font-bold">{title}</h3><button onClick={onClose} aria-label="Close" className="grid h-11 w-11 place-items-center rounded-xl border"><X size={18}/></button></div>{children}</section></div>}
const input='mt-2 min-h-11 w-full rounded-xl border border-slate-200 bg-white px-3 outline-none focus:border-blue-600 focus:ring-2 focus:ring-blue-100';

export function ExternalBilling({clients=[]}){
  const [tab,setTab]=useState('Invoices');const [overview,setOverview]=useState(null);const [invoices,setInvoices]=useState([]);const [services,setServices]=useState([]);const [payments,setPayments]=useState([]);const [state,setState]=useState('loading');const [error,setError]=useState('');const [search,setSearch]=useState('');const [status,setStatus]=useState('');const [modal,setModal]=useState(null);
  const clientName=id=>clients.find(item=>String(item.id)===String(id))?.displayName||'Client';
  async function load(){setState('loading');setError('');try{const [summary,invoicePage,servicePage,paymentPage]=await Promise.all([getBillingOverview(),listInvoices(),listBillableServices(true),listPayments()]);setOverview(summary);setInvoices(invoicePage.items||[]);setServices(servicePage.items||[]);setPayments(paymentPage.items||[]);setState('ready')}catch(reason){setError(reason.message||'Billing data could not be loaded.');setState('error')}}
  useEffect(()=>{void load()},[]);
  const visible=useMemo(()=>invoices.filter(item=>(!status||item.status===status)&&(!search||`${item.invoice_number||''} ${clientName(item.client_id)}`.toLowerCase().includes(search.toLowerCase()))),[invoices,status,search,clients]);
  async function saveService(event){event.preventDefault();try{const f=modal.form;await createBillableService({name:f.name,description:f.description||null,category:f.category||null,default_price_minor:Math.round(Number(f.price)*100),currency:f.currency,default_tax_type:f.tax_type,default_tax_rate_bps:Math.round(Number(f.tax_rate)*100),active:true});setModal(null);await load()}catch(reason){setError(reason.message)}}
  async function saveInvoice(event){event.preventDefault();try{const f=modal.form;const result=await createInvoice({client_id:f.client_id,currency:f.currency,issue_date:f.issue_date||null,due_date:f.due_date||null,client_package_id:null,appointment_id:null,notes:f.notes||null,terms:f.terms||null,items:f.items.map(line=>({service_id:line.service_id||null,description:line.description,quantity:Number(line.quantity),unit_price_minor:Math.round(Number(line.unit_price)*100),discount_type:line.discount_type,discount_value:line.discount_type==='PERCENTAGE'?Math.round(Number(line.discount_value)*100):Math.round(Number(line.discount_value)*100),tax_type:line.tax_type,tax_rate_bps:Math.round(Number(line.tax_rate)*100)}))});setModal({kind:'detail',id:result.id});await load()}catch(reason){setError(reason.message)}}
  async function openDetail(id){try{setModal({kind:'detail',id,data:await getInvoice(id)})}catch(reason){setError(reason.message)}}
  async function doIssue(id){try{await issueInvoice(id);await load();await openDetail(id)}catch(reason){setError(reason.message)}}
  async function pay(event){event.preventDefault();try{const f=modal.payment;await recordInvoicePayment(modal.id,{amount_minor:Math.round(Number(f.amount)*100),currency:modal.data.currency,method:f.method,provenance:'MANUAL_RECORDED',reference_number:f.reference||null,payment_date:f.date,notes:f.notes||null});await load();await openDetail(modal.id)}catch(reason){setError(reason.message)}}
  const newInvoice=()=>setModal({kind:'invoice',form:{client_id:'',currency:'INR',issue_date:today(),due_date:today(),notes:'',terms:'',items:[emptyLine()]}});
  return <div className="space-y-6"><header className="flex flex-col justify-between gap-5 rounded-[28px] bg-slate-950 p-6 text-white sm:flex-row sm:items-end sm:p-8"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-amber-300">Practice finance</p><h2 className="mt-2 text-3xl font-bold">Billing</h2><p className="mt-2 max-w-2xl text-sm text-slate-300">Issue governed invoices and record externally completed payments. No payment collection or card data is used.</p></div><button onClick={newInvoice} className="min-h-11 rounded-xl bg-white px-4 text-sm font-bold text-slate-950"><Plus size={16} className="mr-2 inline"/>New invoice</button></header>
    {error&&<p role="alert" className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</p>}<p className="rounded-2xl border border-blue-100 bg-blue-50 p-4 text-sm text-blue-900">Issued invoice corrections use credit notes. Refunds remain requested, approved, processing, refunded, or failed; refunded requires provider or manual settlement evidence.</p>
    {state==='loading'?<p className="rounded-3xl bg-white p-10 text-center text-sm text-slate-500">Loading billing truth…</p>:state==='error'?<button onClick={load} className="min-h-11 rounded-xl bg-slate-950 px-5 font-bold text-white">Retry billing</button>:<>
      <section aria-label="Billing overview" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[['Outstanding',money(overview?.outstanding_minor),CircleDollarSign],['Paid this month',money(overview?.paid_this_month_minor),ReceiptIndianRupee],['Overdue invoices',overview?.overdue_count??0,FileText],['Open invoices',overview?.open_count??0,FileText]].map(([label,value,Icon])=><article key={label} className="rounded-3xl border border-slate-200 bg-white p-5"><Icon size={19} className="text-blue-700"/><p className="mt-5 text-2xl font-bold">{value}</p><p className="mt-1 text-sm text-slate-500">{label}</p></article>)}</section>
      <nav className="flex gap-2 overflow-x-auto" aria-label="Billing sections">{['Invoices','Payments','Services'].map(item=><button key={item} onClick={()=>setTab(item)} aria-current={tab===item?'page':undefined} className={`min-h-11 rounded-xl px-4 text-sm font-bold ${tab===item?'bg-slate-950 text-white':'border bg-white text-slate-600'}`}>{item}</button>)}</nav>
      {tab==='Invoices'&&<section className="overflow-hidden rounded-3xl border border-slate-200 bg-white"><div className="flex flex-col gap-3 border-b p-4 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3.5 text-slate-400" size={17}/><input aria-label="Search invoices" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Invoice number or client" className="min-h-11 w-full rounded-xl border bg-slate-50 pl-10 pr-3"/></label><select aria-label="Invoice status filter" value={status} onChange={e=>setStatus(e.target.value)} className="min-h-11 rounded-xl border px-3"><option value="">All statuses</option>{['DRAFT','ISSUED','PART_PAID','PAID','OVERDUE','CANCELLED'].map(item=><option key={item}>{item}</option>)}</select></div><div className="divide-y">{visible.map(item=><button key={item.id} onClick={()=>openDetail(item.id)} className="grid min-h-24 w-full gap-2 p-4 text-left hover:bg-slate-50 sm:grid-cols-[1fr_1.3fr_repeat(3,.8fr)] sm:items-center"><strong>{item.invoice_number||'Draft'}</strong><span>{clientName(item.client_id)}</span><span>{money(item.grand_total_minor,item.currency)}</span><span>{money(item.balance_due_minor,item.currency)} due</span><span className="text-xs font-bold text-blue-700">{item.status}</span></button>)}{!visible.length&&<p className="p-10 text-center text-sm text-slate-500">No invoices match this view.</p>}</div></section>}
      {tab==='Payments'&&<section className="rounded-3xl border bg-white p-5"><h3 className="text-lg font-bold">Payment ledger</h3><div className="mt-4 divide-y">{payments.map(item=><article key={item.id} className="flex flex-col justify-between gap-2 py-4 sm:flex-row"><div><p className="font-semibold">{clientName(item.client_id)} · {item.invoice_number}</p><p className="text-sm text-slate-500">{item.method.replaceAll('_',' ')} · {item.provenance.replaceAll('_',' ')}</p></div><strong>{money(item.amount_minor,item.currency)}</strong></article>)}{!payments.length&&<p className="py-8 text-sm text-slate-500">No externally completed payments have been recorded.</p>}</div></section>}
      {tab==='Services'&&<section className="rounded-3xl border bg-white p-5"><div className="flex items-center justify-between"><div><h3 className="text-lg font-bold">Service catalogue</h3><p className="text-sm text-slate-500">Reusable billing defaults; invoice snapshots remain independent.</p></div><button onClick={()=>setModal({kind:'service',form:{name:'',description:'',category:'',price:'',currency:'INR',tax_type:'NO_TAX',tax_rate:'0'}})} className="min-h-11 rounded-xl bg-blue-700 px-4 text-sm font-bold text-white">Add service</button></div><div className="mt-4 grid gap-3 sm:grid-cols-2">{services.map(item=><article key={item.id} className="rounded-2xl border p-4"><div className="flex justify-between gap-3"><strong>{item.name}</strong><span className="text-sm font-bold">{money(item.default_price_minor,item.currency)}</span></div><p className="mt-2 text-sm text-slate-500">{item.description||'No description'} · {item.default_tax_type.replaceAll('_',' ')}</p></article>)}</div></section>}
    </>}
    {modal?.kind==='service'&&<Modal title="Add billable service" onClose={()=>setModal(null)}><form onSubmit={saveService} className="mt-5 grid gap-4"><Field label="Service name"><input required className={input} value={modal.form.name} onChange={e=>setModal({...modal,form:{...modal.form,name:e.target.value}})}/></Field><Field label="Description"><textarea className={input} value={modal.form.description} onChange={e=>setModal({...modal,form:{...modal.form,description:e.target.value}})}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Price"><input required type="number" min="0" step=".01" className={input} value={modal.form.price} onChange={e=>setModal({...modal,form:{...modal.form,price:e.target.value}})}/></Field><Field label="Tax rule"><select className={input} value={modal.form.tax_type} onChange={e=>setModal({...modal,form:{...modal.form,tax_type:e.target.value}})}><option>NO_TAX</option><option>CGST_SGST</option><option>IGST</option><option>CUSTOM_TAX</option></select></Field><Field label="Tax rate %"><input type="number" min="0" max="100" step=".01" className={input} value={modal.form.tax_rate} onChange={e=>setModal({...modal,form:{...modal.form,tax_rate:e.target.value}})}/></Field></div><button className="min-h-12 rounded-xl bg-slate-950 font-bold text-white">Save service</button></form></Modal>}
    {modal?.kind==='invoice'&&<InvoiceForm modal={modal} setModal={setModal} clients={clients} services={services} onSubmit={saveInvoice}/>}
    {modal?.kind==='detail'&&modal.data&&<InvoiceDetail modal={modal} setModal={setModal} clientName={clientName} onIssue={doIssue} onPay={pay}/>}
  </div>
}

function InvoiceForm({modal,setModal,clients,services,onSubmit}){const f=modal.form;const set=(key,value)=>setModal({...modal,form:{...f,[key]:value}});const updateLine=(index,key,value)=>set('items',f.items.map((line,i)=>i===index?{...line,[key]:value}:line));return <Modal title="Create invoice draft" onClose={()=>setModal(null)}><form onSubmit={onSubmit} className="mt-5 space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Client"><select required className={input} value={f.client_id} onChange={e=>set('client_id',e.target.value)}><option value="">Select client</option>{clients.map(item=><option key={item.id} value={item.id}>{item.displayName}</option>)}</select></Field><Field label="Currency"><input required maxLength="3" className={input} value={f.currency} onChange={e=>set('currency',e.target.value.toUpperCase())}/></Field><Field label="Issue date"><input type="date" className={input} value={f.issue_date} onChange={e=>set('issue_date',e.target.value)}/></Field><Field label="Due date"><input type="date" className={input} value={f.due_date} onChange={e=>set('due_date',e.target.value)}/></Field></div><div className="space-y-3">{f.items.map((line,index)=><fieldset key={index} className="rounded-2xl border p-4"><legend className="px-2 text-sm font-bold">Item {index+1}</legend><Field label="Service"><select className={input} value={line.service_id} onChange={e=>{const service=services.find(item=>item.id===e.target.value);set('items',f.items.map((item,i)=>i===index?{...item,service_id:e.target.value,description:service?.name||item.description,unit_price:service?service.default_price_minor/100:item.unit_price,tax_type:service?.default_tax_type||item.tax_type,tax_rate:service?service.default_tax_rate_bps/100:item.tax_rate}:item))}}><option value="">Custom line</option>{services.filter(item=>item.active).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Description"><input required className={input} value={line.description} onChange={e=>updateLine(index,'description',e.target.value)}/></Field><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Field label="Quantity"><input required type="number" min="1" className={input} value={line.quantity} onChange={e=>updateLine(index,'quantity',e.target.value)}/></Field><Field label="Unit price"><input required type="number" min="0" step=".01" className={input} value={line.unit_price} onChange={e=>updateLine(index,'unit_price',e.target.value)}/></Field><Field label="Tax"><select className={input} value={line.tax_type} onChange={e=>updateLine(index,'tax_type',e.target.value)}><option>NO_TAX</option><option>CGST_SGST</option><option>IGST</option><option>CUSTOM_TAX</option></select></Field><Field label="Tax %"><input type="number" min="0" max="100" step=".01" className={input} value={line.tax_rate} onChange={e=>updateLine(index,'tax_rate',e.target.value)}/></Field></div></fieldset>)}</div><button type="button" onClick={()=>set('items',[...f.items,emptyLine()])} className="min-h-11 rounded-xl border px-4 text-sm font-bold">Add line</button><button className="min-h-12 w-full rounded-xl bg-slate-950 font-bold text-white">Save draft</button></form></Modal>}
function InvoiceDetail({modal,setModal,clientName,onIssue,onPay}){const d=modal.data;return <Modal title={d.invoice_number||'Invoice draft'} onClose={()=>setModal(null)}><div className="mt-5"><div className="grid gap-3 rounded-2xl bg-slate-50 p-4 sm:grid-cols-3"><div><small>Client</small><p className="font-bold">{clientName(d.client_id)}</p></div><div><small>Status</small><p className="font-bold">{d.status}</p></div><div><small>Balance</small><p className="font-bold">{money(d.balance_due_minor,d.currency)}</p></div></div><div className="mt-5 divide-y">{d.items.map(item=><div key={item.id} className="flex justify-between gap-3 py-3"><span>{item.description} × {item.quantity}</span><strong>{money(item.line_total_minor,d.currency)}</strong></div>)}</div><div className="mt-5 space-y-2 border-t pt-4 text-sm"><p className="flex justify-between"><span>Subtotal</span><strong>{money(d.subtotal_minor,d.currency)}</strong></p><p className="flex justify-between"><span>Discount</span><strong>−{money(d.discount_amount_minor,d.currency)}</strong></p><p className="flex justify-between"><span>Tax</span><strong>{money(d.tax_total_minor,d.currency)}</strong></p><p className="flex justify-between text-lg"><span>Total</span><strong>{money(d.grand_total_minor,d.currency)}</strong></p></div>{d.status==='DRAFT'&&<button onClick={()=>onIssue(d.id)} className="mt-5 min-h-12 w-full rounded-xl bg-blue-700 font-bold text-white">Issue invoice</button>}{['ISSUED','PART_PAID','OVERDUE'].includes(d.status)&&<form onSubmit={onPay} className="mt-6 rounded-2xl border p-4"><h4 className="font-bold">Record externally completed payment</h4><div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label="Amount"><input required type="number" min=".01" max={d.balance_due_minor/100} step=".01" className={input} value={modal.payment?.amount||''} onChange={e=>setModal({...modal,payment:{date:today(),method:'UPI',reference:'',notes:'',...(modal.payment||{}),amount:e.target.value}})}/></Field><Field label="Method"><select className={input} value={modal.payment?.method||'UPI'} onChange={e=>setModal({...modal,payment:{date:today(),amount:'',reference:'',notes:'',...(modal.payment||{}),method:e.target.value}})}>{['CASH','BANK_TRANSFER','UPI','CARD_EXTERNAL','PAYMENT_GATEWAY','CHEQUE','OTHER'].map(item=><option key={item}>{item}</option>)}</select></Field><Field label="Payment date"><input required type="date" className={input} value={modal.payment?.date||today()} onChange={e=>setModal({...modal,payment:{amount:'',method:'UPI',reference:'',notes:'',...(modal.payment||{}),date:e.target.value}})}/></Field><Field label="Reference"><input className={input} value={modal.payment?.reference||''} onChange={e=>setModal({...modal,payment:{date:today(),amount:'',method:'UPI',notes:'',...(modal.payment||{}),reference:e.target.value}})}/></Field></div><button className="mt-4 min-h-11 w-full rounded-xl bg-emerald-700 font-bold text-white">Record payment &amp; create receipt</button></form>}</div></Modal>}

export function ClientBillingPanel({clientId}){const [data,setData]=useState(null);const [error,setError]=useState('');useEffect(()=>{getClientBilling(clientId).then(setData).catch(reason=>setError(reason.message))},[clientId]);if(error)return <p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-700">Billing unavailable: {error}</p>;if(!data)return <p className="rounded-xl bg-white p-6 text-sm text-slate-500">Loading billing…</p>;return <section className="rounded-3xl border bg-white p-5"><div className="flex justify-between"><div><h3 className="text-lg font-bold">Billing</h3><p className="text-sm text-slate-500">Read-only billing projection</p></div><strong>{money(data.outstanding_minor)} outstanding</strong></div><div className="mt-4 divide-y">{data.invoices.map(item=><div key={item.id} className="flex justify-between py-3"><span>{item.invoice_number||'Draft'} · {item.status}</span><strong>{money(item.balance_due_minor,item.currency)} due</strong></div>)}{!data.invoices.length&&<p className="py-5 text-sm text-slate-500">No billing history for this client.</p>}</div></section>}
